   <div class="impe-routing-field"><label for="salesCaptureName">Nombre completo</label><input id="salesCaptureName" name="nombre" maxlength="150" required autocomplete="name"></div>
   <div class="impe-routing-field"><label for="salesCapturePhone">Teléfono</label><input id="salesCapturePhone" type="tel" name="telefono" maxlength="40" required autocomplete="tel"></div>
   <div class="impe-routing-field"><label for="salesCaptureEmail">Correo electrónico (opcional)</label><input id="salesCaptureEmail" type="email" name="correo" maxlength="180" autocomplete="email"></div>
   <div class="impe-routing-field"><label for="salesCaptureProgram">Programa educativo de interés (opcional)</label><input id="salesCaptureProgram" name="programa" maxlength="120"></div>
   <div class="impe-routing-field"><label for="salesCaptureNotes">Notas de atención</label><textarea id="salesCaptureNotes" name="notas" rows="3" maxlength="1000"></textarea></div>
